{"command":"cd /workspace && mkdir -p app templates static tests && cat <<'EOF' > app.py
from flask import Flask, redirect, render_template, request, url_for, flash
from datetime import datetime
import csv
import io

app = Flask(__name__)
app.secret_key = 'gamma-j-demo-secret'

store = {
    'info': {},
    'products': [],
    'categories': [],
    'customers': [],
    'orders': [],
    'logs': [],
    'notifications': [],
    'issues': [],
}


def add_log(entity, action, detail):
    store['logs'].append({
        'time': datetime.utcnow().isoformat(timespec='seconds') + 'Z',
        'entity': entity,
        'action': action,
        'detail': detail,
    })


def add_notification(kind, message):
    store['notifications'].append({
        'time': datetime.utcnow().isoformat(timespec='seconds') + 'Z',
        'kind': kind,
        'message': message,
    })


def product_key(p):
    return (p.get('name', '').strip().lower(), p.get('sku', '').strip().lower(), p.get('barcode', '').strip().lower())


@app.route('/')
def index():
    return render_template('index.html', store=store)


@app.route('/setup', methods=['GET', 'POST'])
def setup():
    if request.method == 'POST':
        store['info'] = {
            'name': request.form.get('name', '').strip(),
            'email': request.form.get('email', '').strip(),
        }
        if not store['info']['name']:
            flash('Store name is required.', 'error')
            return redirect(url_for('setup'))
        add_log('store', 'setup', f"Store '{store['info']['name']}' created")
        flash('Setup saved.', 'success')
        return redirect(url_for('index'))
    return render_template('setup.html', store=store)


@app.route('/products', methods=['GET', 'POST'])
def products():
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        sku = request.form.get('sku', '').strip()
        price = request.form.get('price', '').strip()
        category = request.form.get('category', '').strip()
        if not name or not sku or not price:
            flash('Name, SKU, and price are required.', 'error')
        else:
            existing = next((p for p in store['products'] if p['sku'].lower() == sku.lower()), None)
            payload = {'name': name, 'sku': sku, 'price': price, 'category': category, 'availability': 'available'}
            if existing:
                existing.update(payload)
                add_log('product', 'update', sku)
            else:
                store['products'].append(payload)
                add_log('product', 'add', sku)
            if category and category not in store['categories']:
                store['categories'].append(category)
            flash('Product saved.', 'success')
        return redirect(url_for('products'))
    return render_template('products.html', store=store)


@app.route('/customers', methods=['GET', 'POST'])
def customers():
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        email = request.form.get('email', '').strip()
        if not name or not email:
            flash('Customer name and email are required.', 'error')
        else:
            store['customers'].append({'name': name, 'email': email})
            add_log('customer', 'add', email)
            flash('Customer saved.', 'success')
        return redirect(url_for('customers'))
    return render_template('customers.html', store=store)


@app.route('/orders', methods=['GET', 'POST'])
def orders():
    if request.method == 'POST':
        customer = request.form.get('customer', '').strip()
        shipping = request.form.get('shipping', '').strip()
        payment = request.form.get('payment', '').strip()
        product = request.form.get('product', '').strip()
        errors = []
        if not customer:
            errors.append('Customer is required.')
        if not shipping:
            errors.append('Shipping address is required.')
        if not payment:
            errors.append('Payment information is required.')
        if errors:
            for e in errors:
                flash(e, 'error')
        else:
            status = 'unpaid' if payment.lower() == 'fail' else 'paid'
            store['orders'].append({'customer': customer, 'shipping': shipping, 'payment': payment, 'product': product, 'status': status})
            if status == 'unpaid':
                store['issues'].append({'type': 'payment', 'priority': 1, 'message': 'Payment failed', 'order': customer})
                add_notification('payment', 'Payment failure needs attention')
            add_log('order', 'create', customer)
            flash('Order submitted.', 'success')
        return redirect(url_for('orders'))
    return render_template('orders.html', store=store)


@app.route('/import', methods=['GET', 'POST'])
def import_products():
    summary = None
    if request.method == 'POST':
        file = request.files.get('file')
        if not file:
            flash('Please upload a CSV file.', 'error')
        else:
            text = file.stream.read().decode('utf-8-sig')
            reader = csv.DictReader(io.StringIO(text))
            imported = skipped = 0
            for row in reader:
                if not row.get('name') or not row.get('sku'):
                    skipped += 1
                    continue
                candidate = {'name': row.get('name', '').strip(), 'sku': row.get('sku', '').strip(), 'price': row.get('price', '').strip(), 'category': row.get('category', '').strip(), 'availability': 'available'}
                existing = next((p for p in store['products'] if product_key(p) == product_key(candidate) or p['sku'].lower() == candidate['sku'].lower()), None)
                if existing:
                    existing.update(candidate)
                else:
                    store['products'].append(candidate)
                imported += 1
            summary = {'imported': imported, 'skipped': skipped}
            add_log('import', 'csv', f"{imported} imported, {skipped} skipped")
            flash(f"Import complete: {imported} imported, {skipped} skipped.", 'success')
    return render_template('import.html', store=store, summary=summary)


@app.route('/logs')
def logs():
    return render_template('logs.html', store=store)


@app.route('/notifications')
def notifications():
    return render_template('notifications.html', store=store)


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8000, debug=True)
EOF

