cat <<'EOF' > tests/test_app.py
import io
from app import app, store


def setup_function():
    for key in store:
        store[key].clear() if isinstance(store[key], list) else store.update({key: {}})


def test_setup_and_product_and_order_flow():
    client = app.test_client()
    assert client.post('/setup', data={'name': 'Shop', 'email': 'a@b.com'}, follow_redirects=True).status_code == 200
    assert client.post('/products', data={'name': 'Widget', 'sku': 'W1', 'price': '9.99', 'category': 'Tools'}, follow_redirects=True).status_code == 200
    assert client.post('/orders', data={'customer': 'Ada', 'shipping': '1 Main St', 'payment': 'card', 'product': 'Widget'}, follow_redirects=True).status_code == 200
    assert store['products'][0]['name'] == 'Widget'
    assert store['orders'][0]['status'] == 'paid'


def test_order_validation_and_payment_failure():
    client = app.test_client()
    resp = client.post('/orders', data={'customer': '', 'shipping': '', 'payment': '', 'product': ''}, follow_redirects=True)
    assert resp.status_code == 200
    assert store['orders'] == []
    client.post('/orders', data={'customer': 'Ada', 'shipping': '1 Main St', 'payment': 'fail', 'product': 'Widget'}, follow_redirects=True)
    assert store['orders'][0]['status'] == 'unpaid'
    assert store['issues'][0]['type'] == 'payment'


def test_csv_import():
    client = app.test_client()
    data = 'name,sku,price,category\nThing,T1,1.25,Stuff\n,NO,2,Stuff\n'
    resp = client.post('/import', data={'file': (io.BytesIO(data.encode()), 'products.csv')}, content_type='multipart/form-data', follow_redirects=True)
    assert resp.status_code == 200
    assert len(store['products']) == 1
EOF

